import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { verifyWebhook, WebhookVerificationError } from "../src/index.js";

/**
 * Vectors produced by the platform's real signers
 * (monorepo libs/webhooks-lib/src/__fixtures__/webhook-signing-vectors.json,
 * generated by its signing-vectors.spec.ts; copied here unchanged). If the
 * platform ever changes how it signs, that spec fails first; copy the new
 * file here in the same change. Test keys only.
 */
interface Vectors {
  tolerance_seconds: number;
  now_unix: number;
  standard: { name: string; secrets: string[]; headers: Record<string, string>; body: string }[];
  legacy: { name: string; secret: string; header: string; value: string; body: string }[];
}
const vectors = JSON.parse(readFileSync(new URL("./fixtures/webhook-signing-vectors.json", import.meta.url), "utf8")) as Vectors;
const now = vectors.now_unix * 1000;

describe("verifyWebhook against the platform's signing vectors", () => {
  it.each(vectors.standard.map((v) => [v.name, v] as const))("standard: %s verifies with each of its secrets", async (_n, v) => {
    for (const secret of v.secrets) {
      await expect(verifyWebhook({ payload: v.body, headers: v.headers, secret, now })).resolves.toEqual(JSON.parse(v.body));
    }
    await expect(verifyWebhook({ payload: `${v.body} `, headers: v.headers, secret: v.secrets[0], now })).rejects.toBeInstanceOf(WebhookVerificationError);
    await expect(
      verifyWebhook({ payload: v.body, headers: v.headers, secret: v.secrets[0], now: now + (vectors.tolerance_seconds + 1) * 1000 }),
    ).rejects.toBeInstanceOf(WebhookVerificationError);
  });

  it.each(vectors.legacy.map((v) => [v.name, v] as const))("legacy: %s verifies", async (_n, v) => {
    await expect(verifyWebhook({ payload: v.body, headers: { [v.header]: v.value }, secret: v.secret, now })).resolves.toEqual(JSON.parse(v.body));
    await expect(verifyWebhook({ payload: v.body, headers: { [v.header]: v.value }, secret: `${v.secret}x`, now })).rejects.toBeInstanceOf(WebhookVerificationError);
  });
});
